def main():
    for l, topics in (("it", IT), ("es", ES)):
        for t in topics:
            assert len(t["drill"]) == 5, t["id"]
            for d in t["drill"]:
                assert d["a"] in d["o"] and len(set(d["o"])) == 3, (t["id"], d)
        json.dump({"topics": topics}, open(os.path.join(D, f"grammar-{l}.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        print(l, "nyelvtan:", len(topics), "téma")


if __name__ == "__main__":
    main()
